# Hypothesis: All connected components transform into their "complete" version
# - 5-pixel shapes become diamonds/crosses
# - 8-pixel ring shapes stay as rings
# - Stack vertically at center column

def create_complete_shape(color, width, height):
    """Create a completed symmetric shape."""
    arr = [[0]*width for _ in range(height)]
    center_w = width // 2
    center_h = height // 2

    # Diamond/+ pattern for 5-pixel shapes (3x3 bounding box)
    if width == 3 and height == 3:
        arr[1][1] = color  # center
        arr[0][1] = color  # top
        arr[1][0] = color  # left
        arr[1][2] = color  # right
        arr[2][1] = color  # bottom
    elif width == 5 and height == 5:
        # Larger diamond
        for r in range(5):
            offset = 2 - abs(r - 2)
            for c in range(offset*2+1):
                arr[r][2+c] = color
                if c > 0:
                    arr[r][offset*2*2-c] = color
    # Ring/O pattern for 8-pixel shapes (3x3)
    elif width == 3 and height == 3:
        for r in [0,2]:
            for c in [0,1,2]:
                arr[r][c] = color
        for c in [0,2]:
            for r in [0,1,2]:
                arr[r][c] = color
        # Clear center
        arr[1][1] = 0

    return arr

